package com.oldbutgold.shop.modules.communication.application;
import com.oldbutgold.shop.modules.communication.api.ChatDtos.*;
import com.oldbutgold.shop.modules.commerce.application.CheckoutService;
import com.oldbutgold.shop.modules.commerce.application.CheckoutDtos.*;
import com.oldbutgold.shop.modules.identity.application.AccountManagementService;
import com.oldbutgold.shop.modules.identity.api.AccountManagementDtos.*;
import com.oldbutgold.shop.modules.platform.application.NotificationService;
import com.oldbutgold.shop.modules.platform.infrastructure.persistence.NotificationRepository;
import com.oldbutgold.shop.modules.communication.infrastructure.media.ChatMediaStorage;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
@EnabledIfEnvironmentVariable(named="OGSHOP_CHAT_TEST_DB_URL",matches=".+")
class ChatOfferPostgresTest {
    @DynamicPropertySource static void database(DynamicPropertyRegistry p) {
        String url=System.getenv("OGSHOP_CHAT_TEST_DB_URL");
        if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/ogshop_chat_test"))throw new IllegalStateException("Dedicated chat test DB required");
        p.add("spring.datasource.url",()->url);p.add("spring.datasource.username",()->System.getenv("OGSHOP_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("OGSHOP_TEST_DB_PASSWORD"));
        p.add("spring.datasource.hikari.connection-init-sql",()->"SET search_path TO og_compat,public");p.add("spring.flyway.enabled",()->true);p.add("spring.jpa.hibernate.ddl-auto",()->"validate");
        p.add("app.chat.upload-dir",()->"target/chat-test-private");p.add("app.cloudinary.url",()->"");p.add("app.cloudinary.cloud-name",()->"");
    }
    @Autowired ChatService chat;@Autowired OfferService offers;@Autowired ChatMediaService media;@Autowired CheckoutService checkout;
    @Autowired AccountManagementService governance;@Autowired NotificationService notifications;@Autowired JdbcTemplate j;@Autowired PlatformTransactionManager manager;@Autowired MockMvc mvc;
    @MockitoSpyBean NotificationRepository outbox;@MockitoSpyBean ChatMediaStorage storage;
    long buyer,seller,other,ktv,product,conversation,address;
    long id(String sql,Object... args){return j.queryForObject(sql,Long.class,args);}
    long user(String... roles){long id=id("INSERT INTO og_compat.users(email,password_hash,full_name) VALUES(?,'{noop}chat-test-1234','Chat QA') RETURNING user_id",UUID.randomUUID()+"@example.invalid");for(String role:roles)j.update("INSERT INTO og_compat.user_roles(user_id,role_id) SELECT ?,role_id FROM og_compat.roles WHERE role_name=?",id,role);return id;}
    @BeforeEach void setup(){reset(outbox,storage);buyer=user("BUYER");seller=user("SELLER");other=user("BUYER");ktv=user("KTV");
        product=new TransactionTemplate(manager).execute(s->{long p=id("INSERT INTO og_compat.products(seller_id,category_id,title,description,listed_price,condition,status,workflow_model) VALUES(?,(SELECT min(category_id) FROM og_compat.categories),'Chat camera','QA fixture',100000,'GOOD','ACTIVE','LEGACY_V14') RETURNING product_id",seller);j.update("INSERT INTO og_compat.product_categories(product_id,category_id) SELECT ?,min(category_id) FROM og_compat.categories",p);return p;});
        address=id("INSERT INTO og_compat.addresses(user_id,recipient_name,phone_number,province,district,ward,detail_address,is_default,ghn_province_id,ghn_district_id,ghn_ward_code) VALUES(?,'QA','0900000000','P','D','W','A',true,201,1442,'20101') RETURNING address_id",buyer);
        id("INSERT INTO og_compat.addresses(user_id,recipient_name,phone_number,province,district,ward,detail_address,is_default,ghn_province_id,ghn_district_id,ghn_ward_code) VALUES(?,'Seller QA','0900000001','P','D','W','A',true,201,1442,'20101') RETURNING address_id",seller);
        conversation=chat.start(buyer,new Start(product,null)).conversation().id();
    }
    @AfterEach void finish(){reset(outbox,storage);}
    Offer propose(){return offers.propose(buyer,conversation,new Proposal(UUID.randomUUID(),new BigDecimal("80000"),null));}
    Decide decide(Decision action,long version){return new Decide(UUID.randomUUID(),action,version,null,null);}
    void restrict(Scope scope){governance.command(ktv,buyer,new Command(Action.RESTRICT,0L,UUID.randomUUID().toString(),"QA restriction",scope,null,null,null,null,null,2,null));}
    MockMultipartFile image(){return new MockMultipartFile("file","qa.png","image/png",Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jX1cAAAAASUVORK5CYII="));}
    @Test void reusesThreadAndProtectsParticipantAndStaff()throws Exception{assertThat(chat.start(buyer,new Start(product,null)).conversation().id()).isEqualTo(conversation);assertThatThrownBy(()->chat.detail(other,conversation,null,50)).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->chat.start(ktv,new Start(product,null))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->chat.start(seller,new Start(product,null))).isInstanceOf(CommunicationException.class);mvc.perform(get("/api/v1/chat/conversations/"+conversation).with(jwt().jwt(t->t.subject(""+other)).authorities(new SimpleGrantedAuthority("ROLE_BUYER")))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/chat/conversations").with(jwt().jwt(t->t.subject(""+ktv)).authorities(new SimpleGrantedAuthority("ROLE_KTV")))).andExpect(status().isForbidden());}
    @Test void messageRetryAndCursorAreMonotonic(){UUID key=UUID.randomUUID();var first=chat.send(buyer,conversation,new Send(key,"Hello",null));assertThat(chat.send(buyer,conversation,new Send(key,"Hello",null)).id()).isEqualTo(first.id());assertThatThrownBy(()->chat.send(buyer,conversation,new Send(key,"Different",null))).isInstanceOf(CommunicationException.class);var second=chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Second",first.id()));assertThat(chat.list(seller,"",0,20).unread()).isEqualTo(2);chat.read(seller,conversation,second.id());chat.read(seller,conversation,first.id());assertThat(chat.detail(buyer,conversation,null,50).peerReadMessageId()).isEqualTo(second.id());assertThat(chat.list(seller,"",0,20).unread()).isZero();}
    @Test void rejectsForeignReplyAndRead(){long c=chat.start(other,new Start(product,null)).conversation().id();long m=chat.send(other,c,new Send(UUID.randomUUID(),"Private",null)).id();assertThatThrownBy(()->chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Reply",m))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->chat.read(buyer,conversation,m)).isInstanceOf(CommunicationException.class);}
    @Test void nativeTextAndQuotaGuards(){assertThatThrownBy(()->j.update("INSERT INTO og_compat.messages(conversation_id,sender_id,client_message_id,message_type,content) VALUES(?,?,?,'TEXT','')",conversation,buyer,UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->j.update("UPDATE public.conversations SET media_quota_usage=jsonb_build_array(jsonb_build_object('sender_id',?::bigint,'images_sent',6,'videos_sent',0,'total_bytes_sent',1)) WHERE conversation_id=?",buyer,conversation)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
    @Test void chatBanPreservesReadButRejectsSendingAndOffers(){restrict(Scope.CHAT);assertThat(chat.detail(buyer,conversation,null,50).canSend()).isFalse();assertThatThrownBy(()->chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Blocked",null))).isInstanceOf(com.oldbutgold.shop.modules.identity.application.RegistrationException.class);assertThatThrownBy(this::propose).isInstanceOf(com.oldbutgold.shop.modules.identity.application.RegistrationException.class);}
    @Test void buyerPurchaseOnlyBanKeepsChat(){restrict(Scope.BUY_ALL);assertThat(chat.detail(buyer,conversation,null,50).canSend()).isTrue();chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Hello",null));assertThat(chat.detail(buyer,conversation,null,50).canOffer()).isFalse();}
    @Test void sellerBlockHasStableAuditAndDeniesNewTransactions(){chat.block(seller,new BlockInput(buyer,"QA",true));chat.block(seller,new BlockInput(buyer,"QA",true));assertThat(id("SELECT count(*) FROM public.audit_logs WHERE entity_type='SELLER_BUYER_BLOCK' AND user_id=?",seller)).isEqualTo(1);assertThatThrownBy(()->chat.send(buyer,conversation,new Send(UUID.randomUUID(),"No",null))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->checkout.getCheckoutPreview(buyer,product,null)).isInstanceOf(CommunicationException.class);chat.block(seller,new BlockInput(buyer,null,false));assertThat(chat.detail(buyer,conversation,null,50).canSend()).isTrue();assertThat(chat.blocks(seller)).isEmpty();}
    @Test void oldOpenOrderKeepsDirectChatAfterSellerBlock(){var order=checkout.buyNow(buyer,new BuyNowRequest(product,address,null,null));chat.block(seller,new BlockInput(buyer,null,true));assertThat(chat.start(seller,new Start(product,order.orderId())).conversation().id()).isEqualTo(conversation);chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Where is my order?",null));assertThat(chat.detail(buyer,conversation,null,50).canOffer()).isFalse();restrict(Scope.CHAT);assertThat(chat.detail(buyer,conversation,null,50).canSend()).isFalse();}
    @Test void proposalIsIdempotentAndOnlyOnePending(){var request=new Proposal(UUID.randomUUID(),new BigDecimal("80000"),null);var a=offers.propose(buyer,conversation,request);assertThat(offers.propose(buyer,conversation,request).id()).isEqualTo(a.id());assertThatThrownBy(this::propose).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->offers.propose(buyer,conversation,new Proposal(request.clientId(),new BigDecimal("90000"),null))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->offers.decide(buyer,a.id(),decide(Decision.ACCEPT,0))).isInstanceOf(CommunicationException.class);}
    @Test void counterChainCanBeAcceptedAndRetried(){var a=propose();var command=new Decide(UUID.randomUUID(),Decision.COUNTER,0,new BigDecimal("85000"),null);var b=offers.decide(seller,a.id(),command);assertThat(b.parentId()).isEqualTo(a.id());assertThat(offers.decide(seller,a.id(),command).id()).isEqualTo(b.id());var accept=decide(Decision.ACCEPT,0);var accepted=offers.decide(buyer,b.id(),accept);assertThat(offers.decide(buyer,b.id(),accept).id()).isEqualTo(accepted.id());assertThat(chat.detail(buyer,conversation,null,50).offers()).extracting(Offer::status).containsExactly("COUNTERED","ACCEPTED");assertThat(j.queryForObject("SELECT status FROM og_compat.products WHERE product_id=?",String.class,product)).isEqualTo("ACTIVE");}
    @Test void invalidCounterRollsBackOldOfferAndOutbox(){var a=propose();long before=id("SELECT count(*) FROM public.outbox_events");assertThatThrownBy(()->offers.decide(seller,a.id(),new Decide(UUID.randomUUID(),Decision.COUNTER,0,BigDecimal.ZERO,null))).isInstanceOf(CommunicationException.class);assertThat(chat.detail(buyer,conversation,null,50).offers().getFirst().status()).isEqualTo("PENDING");assertThat(id("SELECT count(*) FROM public.outbox_events")).isEqualTo(before);}
    @Test void rejectAndWithdrawRequireCorrectActorAndVersion(){var a=propose();assertThatThrownBy(()->offers.decide(seller,a.id(),decide(Decision.WITHDRAW,0))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->offers.decide(seller,a.id(),decide(Decision.REJECT,9))).isInstanceOf(CommunicationException.class);assertThat(offers.decide(seller,a.id(),decide(Decision.REJECT,0)).status()).isEqualTo("REJECTED");var b=propose();assertThat(offers.decide(buyer,b.id(),decide(Decision.WITHDRAW,0)).status()).isEqualTo("WITHDRAWN");}
    @Test void changedListingPreventsAcceptAndSnapshotMutation(){var a=propose();j.update("UPDATE public.products SET version=version+1 WHERE product_id=?",product);assertThatThrownBy(()->offers.decide(seller,a.id(),decide(Decision.ACCEPT,0))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->j.update("UPDATE public.offers SET offered_item_price=70000 WHERE offer_id=?",a.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
    @Test void expiryStopsAcceptAndAllowsFreshProposal()throws Exception{var a=offers.propose(buyer,conversation,new Proposal(UUID.randomUUID(),new BigDecimal("80000"),Instant.now().plusSeconds(1)));Thread.sleep(1200);offers.expireConversation(conversation);assertThat(chat.detail(buyer,conversation,null,50).offers().getFirst().status()).isEqualTo("EXPIRED");assertThatThrownBy(()->offers.decide(seller,a.id(),decide(Decision.ACCEPT,1))).isInstanceOf(CommunicationException.class);assertThat(propose().status()).isEqualTo("PENDING");}
    @Test void acceptedPriceIsBoundOnceAndCheckoutRetryReturnsSameOrder(){var a=propose();offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));var preview=checkout.getCheckoutPreview(buyer,product,null,a.id());assertThat(preview.listedPrice()).isEqualByComparingTo("100000");assertThat(preview.agreedPrice()).isEqualByComparingTo("80000");var request=new BuyNowRequest(product,address,null,null,a.id());var order=checkout.buyNow(buyer,request);assertThat(order.subtotal()).isEqualByComparingTo("80000");assertThat(checkout.buyNow(buyer,request).orderId()).isEqualTo(order.orderId());assertThat(id("SELECT count(*) FROM og_compat.conversation_order_links WHERE conversation_id=? AND order_id=?",conversation,order.orderId())).isEqualTo(1);assertThatThrownBy(()->checkout.buyNow(other,new BuyNowRequest(product,address,null,null,a.id()))).isInstanceOf(CommunicationException.class);assertThatThrownBy(()->checkout.buyNow(buyer,new BuyNowRequest(product,address,null,"changed",a.id()))).isInstanceOf(CommunicationException.class);j.update("UPDATE og_compat.orders SET status='CANCELLED',cancelled_at=CURRENT_TIMESTAMP,cancellation_reason='QA cancellation' WHERE order_id=?",order.orderId());assertThatThrownBy(()->checkout.buyNow(buyer,request)).isInstanceOf(CommunicationException.class);}
    @Test void chatOnlyBanDoesNotCancelPreviouslyAcceptedPurchase(){var a=propose();offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));restrict(Scope.CHAT);assertThat(chat.detail(buyer,conversation,null,50).offers().getFirst().canCheckout()).isTrue();assertThat(checkout.buyNow(buyer,new BuyNowRequest(product,address,null,null,a.id())).subtotal()).isEqualByComparingTo("80000");}
    @Test void acceptAndRejectRaceHasOnlyOneWinner()throws Exception{var a=propose();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Callable<Boolean> accept=()->{start.await();try{offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));return true;}catch(CommunicationException e){return false;}};Callable<Boolean> reject=()->{start.await();try{offers.decide(seller,a.id(),decide(Decision.REJECT,0));return true;}catch(CommunicationException e){return false;}};var first=pool.submit(accept);var second=pool.submit(reject);start.countDown();assertThat((first.get(20,TimeUnit.SECONDS)?1:0)+(second.get(20,TimeUnit.SECONDS)?1:0)).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void messageRaceWithSameKeyCreatesOneRow()throws Exception{UUID key=UUID.randomUUID();ExecutorService pool=Executors.newFixedThreadPool(2);try{Callable<Long> send=()->chat.send(buyer,conversation,new Send(key,"Same",null)).id();var a=pool.submit(send);var b=pool.submit(send);assertThat(a.get(20,TimeUnit.SECONDS)).isEqualTo(b.get(20,TimeUnit.SECONDS));assertThat(id("SELECT count(*) FROM og_compat.messages WHERE conversation_id=?",conversation)).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void failedOutboxRollsBackMessage(){doThrow(new IllegalStateException("QA outbox failed")).when(outbox).enqueue(anyString(),anyLong(),anyList());assertThatThrownBy(()->chat.send(buyer,conversation,new Send(UUID.randomUUID(),"Atomic",null))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(id("SELECT count(*) FROM og_compat.messages WHERE conversation_id=?",conversation)).isZero();}
    @Test void privateImageRetryQuotaAndExpiry()throws Exception{UUID key=UUID.randomUUID();var a=media.send(buyer,conversation,key,image(),"QA");assertThat(media.send(buyer,conversation,key,image(),"QA").id()).isEqualTo(a.id());assertThat(media.read(seller,a.id()).bytes()).isEqualTo(image().getBytes());assertThatThrownBy(()->media.read(other,a.id())).isInstanceOf(CommunicationException.class);for(int n=0;n<4;n++)media.send(buyer,conversation,UUID.randomUUID(),image(),"");assertThat(chat.detail(buyer,conversation,null,50).quota().images()).isEqualTo(5);assertThatThrownBy(()->media.send(buyer,conversation,UUID.randomUUID(),image(),"")).isInstanceOf(CommunicationException.class);j.update("UPDATE public.messages SET media_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 day' WHERE message_id=?",a.id());media.cleanup(a.id());assertThatThrownBy(()->media.read(buyer,a.id())).isInstanceOf(CommunicationException.class);}
    @Test void openOrderHoldsExpiredMedia(){var a=media.send(buyer,conversation,UUID.randomUUID(),image(),"");checkout.buyNow(buyer,new BuyNowRequest(product,address,null,null));j.update("UPDATE public.messages SET media_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 day' WHERE message_id=?",a.id());media.cleanup(a.id());assertThat(media.read(buyer,a.id()).bytes()).isNotEmpty();}
    @Test void cleanupRetriesProviderFailureWithoutDeletingHistory(){var a=media.send(buyer,conversation,UUID.randomUUID(),image(),"");j.update("UPDATE public.messages SET media_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 day' WHERE message_id=?",a.id());doThrow(new IllegalStateException("QA deletion failed")).when(storage).delete(any());media.cleanup(a.id());assertThat(j.queryForObject("SELECT media_metadata->>'cleanupDone' FROM public.messages WHERE message_id=?",String.class,a.id())).isNull();reset(storage);media.cleanup(a.id());assertThat(j.queryForObject("SELECT media_metadata->>'cleanupDone' FROM public.messages WHERE message_id=?",String.class,a.id())).isEqualTo("true");assertThat(chat.detail(buyer,conversation,null,50).messages().items()).hasSize(1);}
    @Test void noticesArePrivateAndPointBackToConversation(){chat.send(buyer,conversation,new Send(UUID.randomUUID(),"New",null));while(notifications.dispatchBatch()>0){}var list=notifications.list(seller,0,20);assertThat(list.items()).hasSize(1);assertThat(list.items().getFirst().conversationId()).isEqualTo(conversation);assertThat(list.items().getFirst().destination()).isEqualTo("CONVERSATION");assertThat(notifications.list(other,0,20).items()).isEmpty();}
    @Test void concurrentOfferCheckoutReturnsOneOrder()throws Exception{var a=propose();offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));var request=new BuyNowRequest(product,address,null,null,a.id());ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{Callable<Long> run=()->{gate.await();return checkout.buyNow(buyer,request).orderId();};var first=pool.submit(run);var second=pool.submit(run);gate.countDown();assertThat(first.get(20,TimeUnit.SECONDS)).isEqualTo(second.get(20,TimeUnit.SECONDS));assertThat(id("SELECT count(*) FROM og_compat.order_items WHERE accepted_offer_id=?",a.id())).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void invalidAddressRollsBackOfferBindingAndReservation(){var a=propose();offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));assertThatThrownBy(()->checkout.buyNow(buyer,new BuyNowRequest(product,999999L,null,null,a.id()))).isInstanceOf(RuntimeException.class);assertThat(j.queryForObject("SELECT checkout_request FROM public.offers WHERE offer_id=?",String.class,a.id())).isNull();assertThat(j.queryForObject("SELECT status FROM og_compat.products WHERE product_id=?",String.class,product)).isEqualTo("ACTIVE");assertThat(checkout.buyNow(buyer,new BuyNowRequest(product,address,null,null,a.id())).subtotal()).isEqualByComparingTo("80000");}
    @Test void reportedMessageIsHeldBeforeCleanup(){var a=media.send(buyer,conversation,UUID.randomUUID(),image(),"");j.update("INSERT INTO og_compat.reports(reporter_id,reported_user_id,message_id,reason) VALUES(?,?,?,'OTHER')",seller,buyer,a.id());assertThat(j.queryForObject("SELECT media_status FROM public.messages WHERE message_id=?",String.class,a.id())).isEqualTo("HOLD_FOR_DISPUTE");j.update("UPDATE public.messages SET media_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 day' WHERE message_id=?",a.id());media.cleanup(a.id());assertThat(media.read(seller,a.id()).bytes()).isNotEmpty();}
    @Test void negotiatedOrderNoticeCommitsOnceWithCheckout(){var a=propose();offers.decide(seller,a.id(),decide(Decision.ACCEPT,0));var request=new BuyNowRequest(product,address,null,null,a.id());var order=checkout.buyNow(buyer,request);checkout.buyNow(buyer,request);while(notifications.dispatchBatch()>0){}assertThat(notifications.list(seller,0,20).items().stream().filter(n->n.type().equals("OFFER_ORDERED")).toList()).hasSize(1);assertThat(notifications.list(buyer,0,20).items().stream().filter(n->n.type().equals("OFFER_ORDERED")).toList()).hasSize(1);assertThat(id("SELECT count(*) FROM og_compat.order_items WHERE order_id=?",order.orderId())).isEqualTo(1);}
}
